package org.sleepwell.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import com.google.android.gms.common.*;import com.google.android.gms.location.*;import java.time.ZoneId;import java.util.*;
/** Google confidence is an optional extra gate for one visible, bounded stillness arm. */
final class GoogleSleepSignal implements AutoCloseable {
 static final String EXTRA="googleSleepEstimate",ACTION="org.sleepwell.GOOGLE_SLEEP_CLASSIFY";static final long FRESH=15*60000L;private static volatile GoogleSleepSignal current;
 final String token=UUID.randomUUID().toString(),zone=ZoneId.systemDefault().getId();final long armedWall=System.currentTimeMillis(),armedElapsed=SystemClock.elapsedRealtime();final Context app;final Runnable changed;final PendingIntent callback;final Handler main=new Handler(Looper.getMainLooper());private boolean closed,registered;private String issue="Registering Google sleep estimates…";private long event;private int confidence=-1;
 static String unavailable(Context c){if(c.getPackageManager().hasSystemFeature(PackageManager.FEATURE_WATCH))return "Google Sleep API is unavailable on watches.";int status=GoogleApiAvailability.getInstance().isGooglePlayServicesAvailable(c);if(status!=ConnectionResult.SUCCESS)return "Google Play services is missing, disabled or needs an update.";if(c.checkSelfPermission(Manifest.permission.ACTIVITY_RECOGNITION)!=PackageManager.PERMISSION_GRANTED)return "Allow Physical activity access for Google sleep estimates.";return "";}
 static GoogleSleepSignal open(Context c,Runnable changed){if(Looper.myLooper()!=Looper.getMainLooper())throw new IllegalStateException("Arm Google estimates from the visible start flow.");String unavailable=unavailable(c);if(!unavailable.isEmpty())throw new IllegalStateException(unavailable);String old=Prefs.text(c,"googleSleepSubscription","");if(!old.isEmpty()){remove(c,old,null);throw new IllegalStateException("Cleaning up the previous Google subscription. Arm again shortly.");}if(current!=null)throw new IllegalStateException("Another Google sleep estimate wait is already active.");return new GoogleSleepSignal(c,changed);}
 private GoogleSleepSignal(Context c,Runnable changed){app=c.getApplicationContext();this.changed=changed;callback=pending(app,token);if(!Prefs.of(app).edit().putString("googleSleepSubscription",token).putString("googleSleepStatus",issue).commit())throw new IllegalStateException("Google estimate ownership could not be stored.");current=this;try{if(app.checkSelfPermission(Manifest.permission.ACTIVITY_RECOGNITION)!=PackageManager.PERMISSION_GRANTED)throw new SecurityException("Physical activity access was revoked.");ActivityRecognition.getClient(app).requestSleepSegmentUpdates(callback,new SleepSegmentRequest(SleepSegmentRequest.CLASSIFY_EVENTS_ONLY)).addOnSuccessListener(main::post,unused->{if(closed){remove(app,token,callback);return;}registered=true;issue="Waiting for a fresh Google sleep estimate (updates can take 10 min or more).";publish();}).addOnFailureListener(main::post,error->{if(closed){remove(app,token,callback);return;}registered=false;issue="Google sleep registration failed. Cancel and arm again, or turn this option off.";publish();});}catch(RuntimeException failure){closed=true;if(current==this)current=null;remove(app,token,callback);throw failure;}}
 boolean ready(){if(closed)return false;String access=unavailable(app);if(!access.isEmpty()){issue=access;return false;}if(!clockValid()){issue="Clock or time zone changed. Cancel and arm again.";return false;}return registered&&event>=armedWall&&confidence>=80&&System.currentTimeMillis()>=event&&System.currentTimeMillis()-event<=FRESH;}
 String status(){if(closed)return "Google sleep estimates stopped.";String access=unavailable(app);if(!access.isEmpty())return access;if(!clockValid())return "Clock or time zone changed. Cancel and arm again.";if(!registered||event==0)return issue;long age=System.currentTimeMillis()-event;if(age<0||age>FRESH)return "Google sleep estimate is stale; waiting for a fresh update.";return "Google sleep estimate "+confidence+"/100 · "+age/60000+" min old"+(confidence<80?" · waiting for at least 80/100":" · stillness and screen-off checks also required");}
 private boolean clockValid(){long elapsed=SystemClock.elapsedRealtime()-armedElapsed,wall=System.currentTimeMillis()-armedWall;return elapsed>=0&&elapsed<AutomaticSleep.MAX_WAIT&&Math.abs(wall-elapsed)<=60000&&zone.equals(ZoneId.systemDefault().getId());}
 private void accept(Intent incoming){if(closed||current!=this||!registered||!clockValid()||!unavailable(app).isEmpty())return;try{if(!SleepClassifyEvent.hasEvents(incoming))return;List<SleepClassifyEvent> rows=SleepClassifyEvent.extractEvents(incoming);if(rows.size()>64)return;long now=System.currentTimeMillis();for(SleepClassifyEvent row:rows){long at=row.getTimestampMillis();int value=row.getConfidence();if(at<armedWall||at<=event||at>now||now-at>FRESH||value<0||value>100||row.getLight()<1||row.getLight()>6||row.getMotion()<1||row.getMotion()>6)continue;event=at;confidence=value;}publish();}catch(RuntimeException invalid){issue="Google sleep event could not be read; waiting for another estimate.";event=0;confidence=-1;publish();}}
 private void publish(){Prefs.put(app,"googleSleepStatus",status());if(!closed&&current==this)changed.run();}
 @Override public void close(){if(closed)return;closed=true;registered=false;if(current==this)current=null;remove(app,token,callback);}
 static void receive(Context c,Intent intent){if(intent==null||!ACTION.equals(intent.getAction())||intent.getData()==null)return;Uri data=intent.getData();if(!"sleepwell".equals(data.getScheme())||!"google-sleep".equals(data.getHost()))return;String token=data.getLastPathSegment();if(token==null||!token.matches("[0-9a-f-]{36}"))return;GoogleSleepSignal owner=current;if(owner!=null&&owner.token.equals(token)&&!owner.closed){owner.accept(intent);return;}if(token.equals(Prefs.text(c,"googleSleepSubscription","")))remove(c,token,null);}
 static void recover(Context c){String token=Prefs.text(c,"googleSleepSubscription","");if(!token.isEmpty()&&(current==null||!current.token.equals(token)))remove(c,token,null);}
 private static void remove(Context c,String token,PendingIntent known){Context app=c.getApplicationContext();PendingIntent pi=known==null?pending(app,token):known;try{ActivityRecognition.getClient(app).removeSleepSegmentUpdates(pi).addOnSuccessListener(unused->{pi.cancel();if(token.equals(Prefs.text(app,"googleSleepSubscription","")))Prefs.of(app).edit().remove("googleSleepSubscription").putString("googleSleepStatus","Google sleep estimates stopped.").apply();}).addOnFailureListener(error->{if(token.equals(Prefs.text(app,"googleSleepSubscription","")))Prefs.put(app,"googleSleepStatus","Google update removal needs attention. Reopen Automatic tracking to retry cleanup.");});}catch(RuntimeException unavailable){Prefs.put(app,"googleSleepStatus","Google update removal needs attention. Reopen Automatic tracking to retry cleanup.");}}
 private static PendingIntent pending(Context c,String token){Intent intent=new Intent(c,GoogleSleepSignalReceiver.class).setPackage(c.getPackageName()).setAction(ACTION).setData(Uri.parse("sleepwell://google-sleep/"+token));/* GMS must fill classification extras; controls elsewhere remain immutable. */return PendingIntent.getBroadcast(c,7541,intent,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0));}
}
